function normalizeDisplayName(rawName, fallback = "Lenzo User") {
	const cleaned = (rawName || fallback).trim().replace(/\s+/g, " ");
	if (cleaned.length < 2) return fallback;
	return cleaned.slice(0, 60);
}
/**
* Create or sync user in Firestore `users/{uid}`
*/
async function syncUserInFirestore(user, authProvider, extra) {
	const userRef = doc(db, "users", user.uid);
	const now = (/* @__PURE__ */ new Date()).toISOString();
	try {
		const existingSnap = await getDoc(userRef);
		if (existingSnap.exists()) {
			const existingData = existingSnap.data();
			const updatePayload = {
				lastLogin: now,
				isOnline: true
			};
			if (!existingData.fullName || existingData.fullName.trim().length < 2) updatePayload.fullName = normalizeDisplayName(extra?.fullName || user.displayName, "Lenzo User");
			if (extra?.profileImage && !existingData.profileImage) updatePayload.profileImage = extra.profileImage;
			await updateDoc(userRef, updatePayload);
			return {
				...existingData,
				...updatePayload
			};
		} else {
			const safeFullName = normalizeDisplayName(extra?.fullName || user.displayName, "Lenzo User");
			const newUserData = {
				uid: user.uid,
				fullName: safeFullName,
				email: (user.email || "").slice(0, 120),
				profileImage: (extra?.profileImage || user.photoURL || DEFAULT_AVATARS[Math.floor(Math.random() * DEFAULT_AVATARS.length)]).slice(0, 1500),
				authProvider,
				createdAt: now,
				lastLogin: now,
				isOnline: true,
				followersCount: 0,
				followingCount: 0,
				level: 0,
				coins: 0,
				diamonds: 0,
				vipLevel: 0,
				accountStatus: "active"
			};
			await setDoc(userRef, newUserData);
			return newUserData;
		}
	} catch (err) {
		handleFirestoreError(err, OperationType.WRITE, `users/${user.uid}`);
		throw err;
	}
}
/**
* Check if the user is returning from a Google redirect authentication flow (with error reporting)
*/
async function checkRedirectAuthOutcome() {
	try {
		const result = await getRedirectResult(auth);
		if (result && result.user) {
			console.log("[Google Auth] Successfully received redirect authentication for UID:", result.user.uid);
			const firestoreData = await syncUserInFirestore(result.user, "google", {
				fullName: result.user.displayName || void 0,
				profileImage: result.user.photoURL || void 0
			});
			await syncBackendAuthSession(result.user);
			return { profile: mapFirestoreUserToProfile(firestoreData, result.user) };
		}
		return { profile: null };
	} catch (err) {
		console.error("[Google Redirect Result Error]:", err);
		if (err.code === "auth/unauthorized-domain") {
			const currentHost = typeof window !== "undefined" ? window.location.hostname : "lenzoparty.com";
			return {
				profile: null,
				unauthorizedDomain: currentHost,
				error: `Google Sign-In is blocked because "${currentHost}" is not yet added to Firebase Console Authorized Domains.`
			};
		}
		return {
			profile: null,
			error: err?.message || "Google authentication redirect failed."
		};
	}
}
async function syncBackendAuthSession(user) {
	try {
		const idToken = await user.getIdToken();
		if (!idToken) return;
		await apiFetch("/api/auth/session", {
			method: "POST",
			headers: {
				Authorization: `Bearer ${idToken}`,
				"X-Platform": Capacitor.isNativePlatform() ? "android" : "web"
			},
			body: JSON.stringify({
				uid: user.uid,
				email: user.email || "",
				platform: Capacitor.isNativePlatform() ? "android" : "web"
			})
		});
	} catch (err) {
		console.warn("[Backend Auth Sync] Non-blocking notice:", err);
	}
}
/**
* REAL Google Sign-In via Native Android Credential/Play Services OR Firebase Web Popup/Redirect
* Both platforms authenticate into the exact same Firebase project (`confident-drake-3bcxw`) and Firestore DB.
*/
async function signInWithGoogle() {
	try {
		await setPersistence(auth, browserLocalPersistence);
		if (Capacitor.isNativePlatform() && Capacitor.getPlatform() === "android") try {
			const nativeRes = await NativeGoogleAuth.signIn();
			if (!nativeRes?.idToken) throw new Error("Google Sign-In did not return an ID token.");
			const user = (await signInWithCredential(auth, GoogleAuthProvider.credential(nativeRes.idToken))).user;
			const firestoreData = await syncUserInFirestore(user, "google", {
				fullName: nativeRes.displayName || user.displayName || void 0,
				profileImage: nativeRes.photoUrl || user.photoURL || void 0
			});
			await syncBackendAuthSession(user);
			return {
				user,
				profile: mapFirestoreUserToProfile(firestoreData, user)
			};
		} catch (nativeErr) {
			const rawMsg = String(nativeErr?.message || nativeErr || "");
			if (rawMsg.includes("CANCELLED") || rawMsg.includes("12501")) throw new Error("Google Sign-In was cancelled.");
			if (rawMsg.includes("DEVELOPER_ERROR") || rawMsg.includes("status code: 10") || rawMsg.includes("code=10")) throw new Error("Android Google OAuth SHA-1 mismatch (code 10). Add SHA-1 \"FD:CB:00:31:00:EB:BE:8E:C9:D6:89:35:50:58:14:48:BB:03:98:59\" to Firebase Console -> Project Settings -> Android App (com.lenzoparty.app), then download updated google-services.json.");
			throw nativeErr;
		}
		const provider = new GoogleAuthProvider();
		provider.setCustomParameters({ prompt: "select_account" });
		try {
			const user = (await signInWithPopup(auth, provider)).user;
			const firestoreData = await syncUserInFirestore(user, "google", {
				fullName: user.displayName || void 0,
				profileImage: user.photoURL || void 0
			});
			await syncBackendAuthSession(user);
			return {
				user,
				profile: mapFirestoreUserToProfile(firestoreData, user)
			};
		} catch (popupError) {
			if (popupError.code === "auth/popup-blocked" || popupError.code === "auth/cancelled-popup-request" || popupError.code === "auth/operation-not-supported-in-this-environment" || popupError.code === "auth/internal-error") {
				console.warn("[Google Auth] Popup restricted, falling back to full-page redirect flow...");
				await signInWithRedirect(auth, provider);
				return null;
			}
			throw popupError;
		}
	} catch (error) {
		console.error("[Google Auth Error]:", error);
		if (error.code === "auth/popup-closed-by-user") throw new Error("Google Sign-In was cancelled.");
		else if (error.code === "auth/unauthorized-domain") {
			const currentHost = typeof window !== "undefined" ? window.location.hostname : "lenzoparty.com";
			const domainError = /* @__PURE__ */ new Error(`Google Sign-In blocked on "${currentHost}". Add "${currentHost}" to Firebase Console -> Authentication -> Settings -> Authorized Domains, or sign in with Email below.`);
			domainError.code = "auth/unauthorized-domain";
			domainError.unauthorizedDomain = currentHost;
			throw domainError;
		} else if (error.code === "auth/account-exists-with-different-credential") throw new Error("An account already exists with this email using password login. Please sign in with Email.");
		else if (error.code === "auth/user-disabled") throw new Error("This account has been disabled. Please contact support.");
		else if (error.code === "auth/network-request-failed") throw new Error("Network error. Please check your internet connection.");
		throw new Error(error.message || "Google Authentication failed.");
	}
}
/**
* REAL Email & Password Registration via Firebase
*/
async function registerWithEmail(params) {
	try {
		await setPersistence(auth, browserLocalPersistence);
		const user = (await createUserWithEmailAndPassword(auth, params.email, params.password)).user;
		const chosenAvatar = params.profileImage || DEFAULT_AVATARS[0];
		await updateProfile(user, {
			displayName: params.fullName,
			photoURL: chosenAvatar
		}).catch((e) => console.warn("Could not update Auth display name:", e));
		try {
			await sendEmailVerification(user);
		} catch (verifErr) {
			console.warn("[Firebase] Email verification send notice:", verifErr);
		}
		const firestoreData = await syncUserInFirestore(user, "password", {
			fullName: params.fullName,
			profileImage: chosenAvatar
		});
		await syncBackendAuthSession(user);
		return {
			user,
			profile: mapFirestoreUserToProfile(firestoreData, user)
		};
	} catch (error) {
		console.error("[Email Register Error]:", error);
		if (error.code === "auth/email-already-in-use") throw new Error("An account with this email address already exists. Please log in instead.");
		else if (error.code === "auth/weak-password") throw new Error("Password should be at least 6 characters.");
		else if (error.code === "auth/invalid-email") throw new Error("Please enter a valid email address.");
		else if (error.code === "auth/operation-not-allowed") throw new Error("Email/Password sign-in is disabled in Firebase Console. Enable it under Authentication -> Sign-in method, or use Google Login.");
		else if (error.code === "auth/network-request-failed") throw new Error("Network error. Please check your internet connection.");
		throw new Error(error.message || "Registration failed.");
	}
}
/**
* REAL Email & Password Login via Firebase
*/
async function loginWithEmail(email, pass, rememberMe = true) {
	try {
		await setPersistence(auth, rememberMe ? browserLocalPersistence : browserSessionPersistence);
		const user = (await signInWithEmailAndPassword(auth, email, pass)).user;
		const firestoreData = await syncUserInFirestore(user, "password");
		await syncBackendAuthSession(user);
		return {
			user,
			profile: mapFirestoreUserToProfile(firestoreData, user)
		};
	} catch (error) {
		console.error("[Email Login Error]:", error);
		if (error.code === "auth/user-not-found" || error.code === "auth/wrong-password" || error.code === "auth/invalid-credential") throw new Error("Invalid email or password. Please check your credentials.");
		else if (error.code === "auth/invalid-email") throw new Error("Please enter a valid email address.");
		else if (error.code === "auth/operation-not-allowed") throw new Error("Email/Password sign-in is disabled in Firebase Console. Enable it under Authentication -> Sign-in method, or use Google Login.");
		else if (error.code === "auth/too-many-requests") throw new Error("Too many failed login attempts. Please reset your password or try again later.");
		else if (error.code === "auth/network-request-failed") throw new Error("Network error. Please check your internet connection.");
		throw new Error(error.message || "Login failed.");
	}
}
