async function deleteChatMessage(chatId, messageId, mode, userId) {
	const docPath = `chats/${chatId}/messages/${messageId}`;
	try {
		if (mode === "for_everyone") await updateDoc(doc(db, "chats", chatId, "messages", messageId), {
			deletedForEveryone: true,
			text: "🚫 This message was deleted"
		});
		else {
			const msgRef = doc(db, "chats", chatId, "messages", messageId);
			const snap = await getDoc(msgRef);
			if (snap.exists()) {
				const deletedForUsers = snap.data().deletedForUsers || [];
				if (!deletedForUsers.includes(userId)) {
					deletedForUsers.push(userId);
					await updateDoc(msgRef, { deletedForUsers });
				}
			}
		}
	} catch (err) {
		handleFirestoreError(err, OperationType.UPDATE, docPath);
	}
}
async function reactToChatMessage(chatId, messageId, emoji, userId, userName) {
	const docPath = `chats/${chatId}/messages/${messageId}`;
	try {
		const msgRef = doc(db, "chats", chatId, "messages", messageId);
		const snap = await getDoc(msgRef);
		if (!snap.exists()) return;
		let reactions = snap.data().reactions || [];
		const existingIndex = reactions.findIndex((r) => r.userId === userId);
		if (existingIndex >= 0) {
			if (reactions[existingIndex].emoji === emoji) reactions.splice(existingIndex, 1);
			else reactions[existingIndex].emoji = emoji;
		} else reactions.push({
			emoji,
			userId,
			userName
		});
		await updateDoc(msgRef, { reactions });
	} catch (err) {
		handleFirestoreError(err, OperationType.UPDATE, docPath);
	}
}
